{
 "add_facts": [
  {
   "content": "As of 2026-04-01, the pager for the indexer rings the Boreal team, not the Atlas team.",
   "entities": ["indexer", "Boreal team", "Atlas team"],
   "kind": "fact",
   "confidence": 0.95,
   "evidence": "From today the pager for the search indexer rings the Boreal team, not team Atlas."
  }
 ],
 "corrections": [
  {
   "old_memory_id": "1000416",
   "new_content": "As of 2026-04-01, the indexer is owned by the Boreal team, taking over from the Atlas team.",
   "entities": ["indexer", "Boreal team", "Atlas team"],
   "kind": "constraint",
   "confidence": 0.95,
   "evidence": "Ownership transferred."
  }
 ],
 "add_relations": [
  {
   "src": "Boreal team",
   "dst": "indexer",
   "rel_kind": "owns",
   "evidence": "Ownership transferred."
  }
 ],
 "remove_relations": [
  {
   "src": "Atlas team",
   "dst": "indexer",
   "rel_kind": "owns",
   "evidence": "Ownership transferred."
  }
 ],
 "entity_aliases": [
  {
   "name": "search indexer",
   "canonical": "indexer",
   "evidence": "the pager for the search indexer rings the Boreal team"
  },
  {
   "name": "team Atlas",
   "canonical": "Atlas team",
   "evidence": "not team Atlas"
  }
 ]
}

